{
  "judgments": [
    {
      "case_id": "PGX31",
      "action": "DENY_UNVERIFIABLE_SOURCE",
      "primary_check": "source_support",
      "reason": "Quoted claim only presents a 2026 addendum label and does not verify the prasugrel requirement."
    },
    {
      "case_id": "PGX32",
      "action": "ABSTAIN_POPULATION_FIT",
      "primary_check": "population_fit",
      "reason": "Annotation marks population_mismatch for same dose estimate without recalibration."
    },
    {
      "case_id": "PGX33",
      "action": "DENY_UNSUPPORTED_ACTION",
      "primary_check": "source_support",
      "reason": "Citation supports PEG interferon-alpha regimens only, not modern HCV medication selection."
    }
  ]
}
